static QString importSummary(const QJsonObject& input,const QJsonObject& preview){
 QStringList lines{"导入预览：仅确认后写入；同名不合并，冲突保留已有。","旧作者、证据级别、信心及营销描述是原记录，不代表独立确认。"};
 for(auto v:input.value("subjects").toArray()){const auto r=v.toObject();lines<<"对象 · "+r.value("subjectType").toString()+" · "+r.value("displayName").toString()+" · "+r.value("platform").toString()+"\n"+r.value("id").toString()+"\n出处 "+r.value("profileUrl").toString()+"\n记录指纹 "+r.value("recordRevision").toString();}
 for(auto v:input.value("sources").toArray()){const auto r=v.toObject();const auto old=r.value("legacyOriginal").toObject();lines<<"来源 · "+r.value("title").toString()+"\n"+r.value("id").toString()+"\n所属对象 "+r.value("subjectId").toString()+"\n链接 "+old.value("sourceUrl").toString()+"\n旧署名 "+old.value("author").toString()+"\n旧发布时间 "+old.value("publishedAt").toString()+"\n旧角色 / 级别 "+old.value("contentRole").toString()+" / "+old.value("evidenceLevel").toString()+QString("\n完整正文 %1 UTF-16字符；全部原记录与未知字段保留\n指纹 ").arg(r.value("text").toString().size())+r.value("recordRevision").toString();}
 for(auto v:input.value("methods").toArray()){const auto r=v.toObject();lines<<"人工方法 · "+r.value("title").toString()+" · "+r.value("versionLabel").toString()+"\n"+r.value("id").toString()+"\n对象版本 "+r.value("subjectRef").toObject().value("id").toString()+"\n状态 "+r.value("assessment").toObject().value("status").toString();for(auto x:r.value("sourceRefs").toArray()){const auto ref=x.toObject();lines<<"关联 "+ref.value("namespace").toString()+"/"+ref.value("kind").toString()+" · "+ref.value("id").toString()+" · "+ref.value("fingerprint").toString();}}
 for(auto v:preview.value("conflicts").toArray())lines<<"保留已有冲突版本 · "+v.toString();return lines.join("\n\n");
}

