PersonMethodPage::~PersonMethodPage(){try{persist();}catch(...) {}}
bool PersonMethodPage::back(){if(views->currentIndex()!=1)return false;views->setCurrentIndex(0);return true;}
void PersonMethodPage::reload(){if(snapshotReader)snapshotReader->request();}
void PersonMethodPage::refresh(){const auto selectedRef=refPicker->currentData().toJsonObject();auto all=catalog;const auto selected=list->currentItem()?list->currentItem()->data(Qt::UserRole).toString():QString{};list->clear();QHash<QString,QJsonObject> subjects;for(auto v:all.value("subjects").toArray())subjects[v.toObject().value("entityId").toString()]=v.toObject();auto filter=search->text().trimmed();for(auto v:all.value(kind()).toArray()){const auto r=v.toObject();auto s=kind()=="subjects"?r:subjects.value(r.value("subjectId").toString());if(kind()=="subjects"&&subjects.value(r.value("entityId").toString()).value("id")!=r.value("id"))continue;if(r.value("archived").toBool()&&reviewFilter->currentData()!="archived")continue;if(!typeFilter->currentData().toString().isEmpty()&&s.value("subjectType")!=typeFilter->currentData())continue;auto review=reviewFilter->currentData().toString();if(!review.isEmpty()&&review!="archived"&&s.value("identityStatus")!=review)continue;if(!filter.isEmpty()&&!QString::fromUtf8(personMethod::json(r)).contains(filter,Qt::CaseInsensitive))continue;auto title=kind()=="subjects"?r.value("displayName").toString():r.value("title").toString();auto item=new QListWidgetItem(title+" · "+(r.value("archived").toBool()?"归档 · ":"")+r.value("id").toString(),list);item->setData(Qt::UserRole,r.value("id").toString());if(r["id"]==selected)list->setCurrentItem(item);}
 refPicker->clear();for(auto v:all.value("sources").toArray()){auto r=v.toObject();refPicker->addItem(r.value("title").toString()+" · "+r.value("id").toString(),personMethod::version("person-method","sources",r.value("id").toString(),r));}for(auto v:externalVersions){auto ref=v.toObject();refPicker->addItem(ref.value("namespace").toString()+"/"+ref.value("kind").toString()+" · "+ref.value("id").toString(),ref);}if(!selectedRef.isEmpty()){int found=-1;for(int i=0;i<refPicker->count();++i)if(refPicker->itemData(i).toJsonObject()==selectedRef){found=i;break;}refPicker->setCurrentIndex(found);}draftTimer.start();}
void PersonMethodPage::load(QJsonObject r){personMethod::need(!r.isEmpty(),"记录已不存在，未替换草稿");baseline=r;draft=r;if(r.value("kind")=="subjects")subjectId=r.value("entityId").toString();else subjectId=r.value("subjectId").toString();references=r.value("sourceRefs").toArray();filling=true;for(auto it=fields.begin();it!=fields.end();++it){QString value=r.value(it.key()).toString();if(r.value("kind")=="sources"&&QStringList{"sourceUrl","author","publishedAt","contentRole","evidenceLevel"}.contains(it.key()))value=r.value("legacyOriginal").toObject().value(it.key()).toString();if(it.key()=="aliases"){QStringList a;for(auto v:r.value("aliases").toArray())a.append(v.toString());value=a.join('\n');}it.value()->setPlainText(value);bool visible=r.value("kind")=="subjects"?QStringList{"subjectType","displayName","platform","profileUrl","aliases","description","identityStatus","identityBasis"}.contains(it.key()):r.value("kind")=="sources"?QStringList{"title","text","sourceUrl","author","publishedAt","contentRole","evidenceLevel"}.contains(it.key()):QStringList{"title","versionLabel","conditions","steps","evidenceQuote","counterexamples","invalidations","interpretation"}.contains(it.key());it.value()->setVisible(visible);findChild<QLabel*>("pmLabel_"+it.key())->setVisible(visible);}refPicker->setEnabled(r.value("kind")=="methods");findChild<QWidget*>("pmRefArea")->setVisible(r.value("kind")=="methods");boundPicker->clear();for(auto v:references){auto ref=v.toObject();boundPicker->addItem(ref.value("namespace").toString()+"/"+ref.value("kind").toString()+" · "+ref.value("id").toString()+" · "+ref.value("fingerprint").toString());}refsLabel->setText(QString("冻结来源版本 %1；仅核对引用字串，不确认作者或有效性").arg(references.size()));auto owner=r.value("kind")=="subjects"?r:r.value("kind")=="methods"?r.value("subjectRef").toObject().value("originalRecord").toObject():store->latest("subjects",subjectId);identity->setText((r.value("kind")=="subjects"?QString("当前编辑对象"):r.value("kind")=="sources"?QString("当前编辑来源版本"):QString("当前编辑人工方法版本"))+" · 关联对象 "+owner.value("displayName").toString("未知 / 未命名")+" · "+r.value("id").toString()+"\n对象身份 "+subjectId+"；来源及身份待独立核实");filling=false;dirty=false;views->setCurrentIndex(0);draftTimer.start();}
void PersonMethodPage::newRecord(){auto k=kind();auto id=QUuid::createUuid().toString(QUuid::WithoutBraces);QJsonObject r{{"kind",k},{"entityId",id},{"id",""},{"parentId",""},{"savedAt",""}};if(k=="subjects"){r["subjectType"]="person";r["identityStatus"]="unverified";r["aliases"]=QJsonArray{};for(auto f:{"displayName","platform","profileUrl","description","identityBasis"})r[f]="";}else{personMethod::need(!subjectId.isEmpty(),"先在对象页选择所属人物、书籍或方法");auto owner=store->latest("subjects",subjectId);personMethod::need(!owner.isEmpty()&&!owner.value("archived").toBool(),"所属对象不存在或已归档");r["subjectId"]=subjectId;r["title"]="";if(k=="sources"){r["text"]="";r["legacyOriginal"]=QJsonObject{{"id",id},{"content",""},{"contentRole","manual_note"},{"evidenceLevel","commentary"}};}else{auto subject=store->latest("subjects",subjectId);personMethod::need(!subject.isEmpty()&&!subject.value("archived").toBool(),"所属对象不存在或已归档");r["subjectRef"]=personMethod::version("person-method","subjects",subject.value("id").toString(),subject);r["sourceRefs"]=QJsonArray{};for(auto f:{"versionLabel","conditions","steps","evidenceQuote","counterexamples","invalidations","interpretation"})r[f]="";}}load(r);baseline={};dirty=false;}
void PersonMethodPage::sync(){if(draft.isEmpty())return;auto k=draft.value("kind").toString();for(auto it=fields.begin();it!=fields.end();++it)if(it.value()->isVisibleTo(views->widget(0))){if(it.key()=="aliases"){QJsonArray a;for(auto line:it.value()->toPlainText().split('\n'))if(!line.trimmed().isEmpty())a.append(line.trimmed());draft["aliases"]=a;}else if(k=="sources"&&QStringList{"sourceUrl","author","publishedAt","contentRole","evidenceLevel"}.contains(it.key())){auto original=draft.value("legacyOriginal").toObject();original[it.key()]=it.value()->toPlainText();draft["legacyOriginal"]=original;}else draft[it.key()]=it.value()->toPlainText();}if(k=="methods")draft["sourceRefs"]=references;}
void PersonMethodPage::save(bool archive){sync();auto r=draft;personMethod::need(!r.isEmpty(),"没有编辑草稿");r["id"]=r.value("entityId").toString()+"@"+QUuid::createUuid().toString(QUuid::WithoutBraces);r["parentId"]=baseline.value("id").toString();r["savedAt"]=QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs);if(archive)r["archived"]=true;if(r.value("kind")=="sources"){auto old=r.value("legacyOriginal").toObject();old["content"]=r.value("text");old.remove("text");old.remove("transcript");old["manualRevision"]=true;old["title"]=r.value("title");r["legacyOriginal"]=old;}auto saved=store->append(r,baseline);load(saved);reload();message("已保存不可变版本；身份与方法有效性仍需独立验证");persist();}
void PersonMethodPage::addReference(){personMethod::need(draft.value("kind")=="methods","只有人工方法可关联来源");auto ref=refPicker->currentData().toJsonObject();personMethod::validateVersion(ref);for(auto v:references)if(personMethod::canonical(v)==personMethod::canonical(ref))return;personMethod::need(references.size()<100,"最多100个来源版本");references.append(ref);sync();dirty=true;boundPicker->clear();for(auto v:references){auto ref=v.toObject();boundPicker->addItem(ref.value("namespace").toString()+"/"+ref.value("kind").toString()+" · "+ref.value("id").toString()+" · "+ref.value("fingerprint").toString());}refsLabel->setText(QString("冻结来源版本 %1；仅核对引用字串，不确认作者或有效性").arg(references.size()));draftTimer.start();}
void PersonMethodPage::showOriginal(QJsonObject ref){personMethod::validateVersion(ref);readerRef=ref;auto raw=ref.value("originalRecord").toObject();reader->setPlainText("完整版本 "+ref.value("id").toString()+"\n指纹 "+ref.value("fingerprint").toString()+"\n\n"+(personMethod::body(raw).isEmpty()?QString("原记录未提供正文或转写；摘要与旧分析仅作为原记录读取"):personMethod::body(raw))+"\n\n完整原记录（含出处、旧分析与未知字段）\n"+QString::fromUtf8(QJsonDocument(raw).toJson(QJsonDocument::Indented)));views->setCurrentIndex(1);}
void PersonMethodPage::locate(){personMethod::need(!dirty,"草稿尚未保存，未离开当前编辑");auto ref=views->currentIndex()==1?readerRef:(boundPicker->currentIndex()>=0&&boundPicker->currentIndex()<references.size()?references[boundPicker->currentIndex()].toObject():QJsonObject{});personMethod::validateVersion(ref);if(ref.value("namespace")=="person-method"){auto current=store->get(ref.value("kind").toString(),ref.value("id").toString());personMethod::need(personMethod::canonical(current)==personMethod::canonical(ref.value("originalRecord")),"来源版本已变化或不存在；保留冻结原文");showOriginal(ref);}else{bool current=false;if(versions)for(auto v:versions())current=current||personMethod::canonical(v)==personMethod::canonical(ref);personMethod::need(current&&bool(opener),"当前完整来源版本无法匹配，未按标题定位");persist();opener(ref);}}
void PersonMethodPage::previewImport(const QByteArray& text){pending={};pendingBaseline={};auto input=personMethod::decode(text);personMethod::need(personMethod::json(input).size()<=32*1024*1024,"转换后超过32MiB，请拆分；未生成不可确认预览");auto current=store->backup();auto p=personMethod::preview(input,current);pending=input;pendingBaseline=current;readerRef={};reader->setPlainText(importSummary(input,p));views->setCurrentIndex(1);message(QString("预览：新增%1，完全重复%2，冲突%3（保留已有）；仅确认后写入").arg(p.value("added").toInt()).arg(p.value("duplicate").toInt()).arg(p.value("conflicts").toArray().size()));persist();}
void PersonMethodPage::confirmImport(){personMethod::need(!pending.isEmpty(),"没有待确认导入");store->merge(pending,pendingBaseline);pending={};pendingBaseline={};reload();views->setCurrentIndex(0);message("导入完成，原草稿及全部旧版本保留；旧营销描述未确认");persist();}
void PersonMethodPage::cancelImport(){pending={};pendingBaseline={};views->setCurrentIndex(0);message("已取消预览，未写入资料库");persist();}
QJsonObject PersonMethodPage::state()const{return {{"schema","person-method-view/v1"},{"baseline",baseline},{"draft",draft},{"references",references},{"subjectId",subjectId},{"dirty",dirty},{"mode",mode->currentIndex()},{"type",typeFilter->currentIndex()},{"review",reviewFilter->currentIndex()},{"search",search->text()},{"pending",pending},{"pendingBaseline",pendingBaseline}};}
void PersonMethodPage::persist()const{personMethod::need(viewWritable,"原草稿尚未通过完整核验，未覆盖文件");QSaveFile f(statePath());auto bytes=personMethod::json(state());personMethod::need(f.open(QIODevice::WriteOnly)&&f.write(bytes)==bytes.size()&&f.commit(),"草稿落盘失败，原状态未覆盖");}
QJsonObject PersonMethodPage::saveState()const{persist();return {{"stateFile",statePath()}};}
void PersonMethodPage::restoreState(const QJsonObject& marker){personMethod::need(marker.value("stateFile").toString()==statePath(),"不是此独立人物方法库的草稿");restore();}
void PersonMethodPage::restore(){viewWritable=false;QFile f(statePath());if(!f.exists()){viewWritable=true;return;}personMethod::need(f.open(QIODevice::ReadOnly),"草稿文件无法读取");auto d=QJsonDocument::fromJson(f.readAll());personMethod::need(d.isObject()&&d.object().value("schema")=="person-method-view/v1","草稿状态损坏，未清空");const auto s=d.object();if(!s.value("baseline").toObject().isEmpty())personMethod::validate(s.value("baseline").toObject());auto r=s.value("draft").toObject();personMethod::need(!r.isEmpty(),"草稿内容缺失");load(r);baseline=s.value("baseline").toObject();references=s.value("references").toArray();subjectId=s.value("subjectId").toString();dirty=s.value("dirty").toBool();pending=s.value("pending").toObject();pendingBaseline=s.value("pendingBaseline").toObject();mode->setCurrentIndex(s.value("mode").toInt());typeFilter->setCurrentIndex(s.value("type").toInt());reviewFilter->setCurrentIndex(s.value("review").toInt());search->setText(s.value("search").toString());refresh();if(!pending.isEmpty()){readerRef={};reader->setPlainText(importSummary(pending,personMethod::preview(pending,pendingBaseline)));views->setCurrentIndex(1);viewWritable=true;message("已恢复待确认预览，尚未写入；原草稿保留");return;}viewWritable=true;message(dirty?"已恢复未保存草稿；保留原版本基线，过期保存将拒绝":"已恢复人物方法库视图");}
